#!/usr/bin/env bash
# Reproduce S10-4 v2x-track submission 's10-4-v4' (model-v2x-track/routed-s10-4-v4): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Exact check without a GPU (the saved member predictions): python common/tools/reproduce_submission.py model-v2x-track/routed-s10-4-v4 --tag s10-4-v4 --saved model-v2x-track/routed-s10-4-v4/submissions/2026-11-13_s10-4-v4/member_predictions_s10-4-v4.zip
# Generated by common/tools/reproduce_submission.py; scored zip model-v2x-track/routed-s10-4-v4/submissions/2026-11-13_s10-4-v4/v2x_s10-4-v4_submission.zip (md5 ea385593f3875b29b2ae85c332c31366).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-s10-4-v4/test/reproduce_s10-4-v4.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-v2x-track/routed-s10-4-v4/test/output/repro_s10-4-v4
mkdir -p $OUT
# member bvrros6x5_tta: seed bag model-v2x-track/bag-voxelrcnn-ros-g1v6x5 (5 seeds, TTA flip4+yaw+z); seeds: model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 22bacfe61e13d7dcc4c8ed5984cc8987), model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 3ff5d89bb83c1d47773565e05dd39a1a), model-v2x-track/voxelrcnn-ros-g1v6d3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 3d18641390357be827c19f1d372ff20c), model-v2x-track/voxelrcnn-ros-g1v6d4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 ab3e1781668e68a7d1b516dd3ae3a52e), model-v2x-track/voxelrcnn-ros-g1v6d5/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 bd4c383f2338875232dda1de02cb6c97)
python common/tools/bag_predictions.py model-v2x-track/bag-voxelrcnn-ros-g1v6x5 --kit --variant tta --refresh --cache-dir $OUT/bag_bvrros6x5_tta --out $OUT/predictions_bvrros6x5_tta.json
# member bvrros6x_tta12: seed bag model-v2x-track/bag-voxelrcnn-ros-g1v6x (2 seeds, TTA flip4+yaw+z+scale); seeds: model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 22bacfe61e13d7dcc4c8ed5984cc8987), model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 3ff5d89bb83c1d47773565e05dd39a1a)
python common/tools/bag_predictions.py model-v2x-track/bag-voxelrcnn-ros-g1v6x --kit --variant tta12 --refresh --cache-dir $OUT/bag_bvrros6x_tta12 --out $OUT/predictions_bvrros6x_tta12.json
# member dsros6_tta: model-v2x-track/dsvt-ros-g1v6, checkpoint md5 04d992cf9397bfd6656cb0c95babd148
python common/tools/pcdet_predict.py model-v2x-track/dsvt-ros-g1v6 --ckpt model-v2x-track/dsvt-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/dsvt-ros-g1v6/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_dsros6_tta.json
# member vrros6_tta12: model-v2x-track/voxelrcnn-ros-g1v6, checkpoint md5 22bacfe61e13d7dcc4c8ed5984cc8987
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out $OUT/predictions_vrros6_tta12.json
# member vrros6d2_tta12: model-v2x-track/voxelrcnn-ros-g1v6d2, checkpoint md5 3ff5d89bb83c1d47773565e05dd39a1a
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d2 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v6d2/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out $OUT/predictions_vrros6d2_tta12.json
# member vrrosf6_tta12: model-v2x-track/voxelrcnn-rosf-g1v6, checkpoint md5 0c587d704f02577bc3691066a3d59aa9
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-rosf-g1v6 --ckpt model-v2x-track/voxelrcnn-rosf-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-rosf-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out $OUT/predictions_vrrosf6_tta12.json
python common/tools/route_predictions.py merge model-v2x-track/routed-s10-4-v4 --pred bvrros6x5_tta=$OUT/predictions_bvrros6x5_tta.json --pred bvrros6x_tta12=$OUT/predictions_bvrros6x_tta12.json --pred dsros6_tta=$OUT/predictions_dsros6_tta.json --pred vrros6_tta12=$OUT/predictions_vrros6_tta12.json --pred vrros6d2_tta12=$OUT/predictions_vrros6d2_tta12.json --pred vrrosf6_tta12=$OUT/predictions_vrrosf6_tta12.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-v2x-track/routed-s10-4-v4 --tag s10-4-v4 --compare $OUT/predictions.json || echo 'predictions differ beyond the equivalence check (see above); packaging continues, the zip comparison at the end gives the verdict'
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/v2x-track/pcdet/g1-v6/points" ]; then SYN=(--syn-split val --syn-list model-v2x-track/routed-s10-4-v4/submissions/2026-11-13_s10-4-v4/synthetic_ids.txt); else SYN=(--syn-zip model-v2x-track/routed-s10-4-v4/submissions/2026-11-13_s10-4-v4/v2x_s10-4-v4_submission.zip --syn-list model-v2x-track/routed-s10-4-v4/submissions/2026-11-13_s10-4-v4/synthetic_ids.txt); fi
python common/tools/package_submission.py model-v2x-track/routed-s10-4-v4 --tag repro-s10-4-v4 --pred $OUT/predictions.json --synthetic pcdet/g1-v6 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of s10-4-v4' --reproduction
Z=model-v2x-track/routed-s10-4-v4/test/output/repro-s10-4-v4/submission.zip
python common/tools/check_submission.py --track v2x $Z --official
python common/tools/reproduce_submission.py model-v2x-track/routed-s10-4-v4 --tag s10-4-v4 --compare-zip $Z     # predictions and frames against the scored zip
